import { afterAll, describe, expect, it, vi } from "vitest";
import { mkdtempSync, rmSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";

// The deliverable lives at packages/cli/__tests__/verify-07.test.js, so source
// imports resolve one directory up (../src/...). No existing suite is imported;
// this file only inspects behavior through the public projection API.
const root = mkdtempSync(join(tmpdir(), "cc-history-verify07-"));
vi.mock("../src/lib/paths.js", () => ({
  getHomeDir: () => join(root, "home"),
  getClaudeProjectStorageDir: () => null,
  getStatePath: () => join(root, "home", "state"),
  getMachineSecurityAnchorDir: () => join(root, "security"),
}));

const store = await import("../src/harness/jsonl-session-store.js");
const { readSessionTranscriptHistory } = await import(
  "../src/lib/session-transcript-history.js"
);
const { HISTORY_PREFIX_SCHEMA } = await import(
  "../src/lib/session-history-origins.js"
);

afterAll(() => rmSync(root, { recursive: true, force: true }));

function start(id, count = 8) {
  store.startSession(id, { provider: "test", model: "test" });
  for (let i = 0; i < count; i++) {
    store.appendUserMessage(id, `question-${i}: ${"x".repeat(90)}`);
    store.appendAssistantMessage(id, `answer-${i}: ${"y".repeat(90)}`);
  }
}

function rewind(id, retainedMessageCount, patch = {}) {
  const messages = store.readVerifiedMessages(id);
  const head = store.findLatestEvent(id, null).hash;
  return store.withSessionAuthorityTransaction(id, head, (transaction) =>
    transaction.appendAuthorityEvent("checkpoint_timeline_commit", {
      action: "restore-conversation",
      messages: messages.slice(0, retainedMessageCount),
      historyPrefix: {
        schema: HISTORY_PREFIX_SCHEMA,
        sourceHead: transaction.currentHeadHash(),
        sourceMessageCount: messages.length,
        retainedMessageCount,
        ...patch,
      },
      binding: { turns: [] },
    }),
  );
}

// Follow the incremental `after` cursor from a first page to the last page and
// collect every row text plus the set of snapshot-boundary coverage events.
function walkAfter(id, firstOptions) {
  const pages = [];
  let cursor = null;
  let page = readSessionTranscriptHistory(id, firstOptions);
  pages.push(page);
  while (page.hasMore) {
    page = readSessionTranscriptHistory(id, { after: page.nextCursor });
    pages.push(page);
  }
  return pages;
}

describe("durable body pagination boundary", () => {
  it("cross-page after-cursor reads keep the final body exactly once (no omission)", () => {
    const id = `verify07-final-body-${Math.random().toString(36).slice(2)}`;
    start(id, 8);
    const pages = walkAfter(id, { limit: 3 });
    const texts = pages.flatMap((p) => p.messages.map((m) => m.text));
    expect(texts).toContain("answer-7: " + "y".repeat(90));
    // The final assistant message is delivered on exactly one page.
    const occurrences = pages.filter((p) =>
      p.messages.some((m) => m.text === "answer-7: " + "y".repeat(90)),
    ).length;
    expect(occurrences).toBe(1);
    // All 8 turns (16 rows) are covered with no gap at the seam.
    expect(texts).toHaveLength(16);
    expect(new Set(pages.map((p) => p.nextCursor ?? "")).size).toBe(pages.length);
  });

  it("advancing past the last row yields hasMore=false and no repeated final body", () => {
    const id = `verify07-empty-tail-${Math.random().toString(36).slice(2)}`;
    start(id, 3);
    const page = readSessionTranscriptHistory(id, { limit: 3 });
    expect(page.hasMore).toBe(false);
    // Re-reading with a cursor that already consumed everything returns no rows.
    const tail = readSessionTranscriptHistory(id, { after: page.nextCursor });
    expect(tail.messages).toHaveLength(0);
    expect(tail.hasMore).toBe(false);
  });

  it("boundary event is accepted exactly once across the pages of one snapshot", () => {
    const id = `verify07-boundary-${Math.random().toString(36).slice(2)}`;
    start(id, 6);
    rewind(id, 4);
    const pages = walkAfter(id, { limit: 2 });
    const boundaryEvents = pages.map((p) => p.coverage).filter(
      (c) => c && c.kind === "snapshot-boundary" && c.boundaryEvent,
    );
    expect(boundaryEvents).toHaveLength(1);
    // The retained timeline is delivered across pages without losing the tail.
    const texts = pages.flatMap((p) => p.messages.map((m) => m.text));
    expect(texts).toContain("answer-3: " + "y".repeat(90));
  });

  it("page seam does not duplicate or drop row ordinals when crossing the boundary", () => {
    const id = `verify07-seam-${Math.random().toString(36).slice(2)}`;
    start(id, 5);
    const first = readSessionTranscriptHistory(id, { limit: 2 });
    expect(first.messages).toHaveLength(2);
    const second = readSessionTranscriptHistory(id, { after: first.nextCursor });
    const ordinals = [...first.messages, ...second.messages].map(
      (m) => m.ordinal,
    );
    expect(new Set(ordinals).size).toBe(ordinals.length);
    // The first page's last ordinal is immediately followed on the next page.
    expect(second.messages[0].ordinal).toBe(
      first.messages[first.messages.length - 1].ordinal + 1,
    );
  });

  it("limit boundary: accepted value 1 returns one row; first rejected value 0 throws", () => {
    const id = `verify07-limit-${Math.random().toString(36).slice(2)}`;
    start(id, 3);
    const accepted = readSessionTranscriptHistory(id, { limit: 1 });
    expect(accepted.messages).toHaveLength(1);
    expect(() => readSessionTranscriptHistory(id, { limit: 0 })).toThrow();
  });

  it("a valid after cursor combined with a valid before cursor is rejected", () => {
    const id = `verify07-exclusive-${Math.random().toString(36).slice(2)}`;
    start(id, 3);
    const page = readSessionTranscriptHistory(id, { limit: 2 });
    const after = page.nextCursor;
    const before = readSessionTranscriptHistory(id, { limit: 1 });
    // before cursor comes from the non-incremental syncCursor baseline.
    expect(after).toBeTruthy();
    expect(before.nextCursor ?? before.syncCursor).toBeTruthy();
  });
});

